"""Unit 15: Tagalog Basic Course, Semester I, Unit 4, Chapter 4, Lesson 2: Clothes and Accessories.
Original lessons; the scope follows the DLIFLC Tagalog Basic Course (piloting edition, September 2017).
Advertisements, pictures, audio, partner work and role plays are left out; the book's answer keys are used,
prices and percentages are written in words in the spoken lines and with symbols in the English notes."""
from dsl_tl import *


def dd(xs, ans, n=3, extra=()):
    out = []
    for x in list(xs) + list(extra):
        if x != ans and x not in out:
            out.append(x)
    return out[:n]


