_MOD = [("medyo mura", "a little inexpensive"), ("medyo maliit", "a little small"), ("medyo bago", "a little new"), ("maliit nang kaunti", "a little small"), ("mura nang kaunti", "a little inexpensive"), ("malaki nang kaunti", "a little bit bigger"), ("matibay-tibay", "a little durable"), ("marami-rami", "a little bit plentiful"), ("mura-mura", "a little cheap/inexpensive"), ("bagu-bago", "a little new"), ("luma-luma", "a little old"), ("malaki-laki", "somewhat big"), ("mababa-baba", "somewhat low"), ("makapal-kapal", "somewhat thick")]
