_MK = [("singular, common noun", "nasa + object/place/person", "wala sa + object/place/person"), ("plural, common noun", "nasa mga + object/place/person", "wala sa mga + object/place/person"), ("singular, proper name", "na kay + proper name", "wala kay + proper name"), ("plural, proper name", "na kina + proper name", "wala kina + proper name")]
